import { ciFailureWork, failureSignature, pullRequestNumbers } from '../core/ci.mjs';

export function createCiMonitor({
  checks,
  snapshot,
  loadBaseline,
  saveBaseline,
  createCheckpoint,
  notify,
  reportHealth,
  owner,
  estimateMs,
  intervalMs = 30_000,
  schedule,
  cancel,
}) {
  let signatures = new Map();
  let activeScope = null;
  const health = new Map();
  let timer = null;
  let busy = false;

  const selectScope = (current) => {
    const scope = String(current.scope ?? 'none');
    if (scope === activeScope) return;
    activeScope = scope;
    signatures = new Map(Object.entries(loadBaseline(current) ?? {}));
    health.clear();
  };
  const persist = (current) => saveBaseline(current, Object.fromEntries(signatures));

  async function poll() {
    if (busy) return;
    busy = true;
    try {
      const current = snapshot();
      selectScope(current);
      for (const number of pullRequestNumbers(current)) {
        try {
          const failures = await checks.failuresFor(number);
          const previousHealth = health.get(number);
          health.set(number, 'ok');
          if (previousHealth && previousHealth !== 'ok') {
            reportHealth({ number, state: 'ok' });
          }
          const signature = failureSignature(failures);
          const previous = signatures.get(String(number));
          signatures.set(String(number), signature);
          persist(current);
          if (!signature || signature === previous) continue;
          const work = ciFailureWork({
            number, failures, items: current.items, owner, estimateMs,
          });
          if (work.checkpoint) createCheckpoint(work.checkpoint);
          await notify(number, work);
        } catch (error) {
          const message = error?.message ?? String(error);
          if (health.get(number) !== message) {
            health.set(number, message);
            reportHealth({ number, state: 'failed', error: message });
          }
        }
      }
    } finally {
      busy = false;
    }
  }

  return {
    start() {
      if (timer) return;
      void poll();
      timer = schedule(() => void poll(), intervalMs);
    },
    stop() {
      if (timer) cancel(timer);
      timer = null;
    },
    poll,
  };
}

{
  "name": "minimac",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "A floor for watching and steering a fleet of AI coding agents.",
  "scripts": {
    "start": "node server.mjs",
    "demo": "node server.mjs --engine sim --mission 'demo run'"
  },
  "engines": { "node": ">=22" }
}

// The composer. One input for everything you can say to the fleet: set the
// mission, steer whoever is selected, and name files, skills or agents inline.
//
// It owns no state beyond what is being typed. Where a message goes and what
// it means are decided by core/mentions.mjs and the server.

import { agentMentionNames, parseMentions } from '../core/mentions.mjs';
import { createMarkdownEditor } from './markdown-editor.mjs';

export const MISSION_TARGET = 'mission';
// Speak once, three ways. MISSION replaces what the run is for. POLICY binds
// every agent on every dispatch and every steer, forever, with no model in the
// path. THOR is the judgement lane: say it once and he decides who needs it.
export const POLICY_TARGET = 'policy';
export const ROUTE_TARGET = 'thor';
export const SPEAK_TARGETS = Object.freeze([
  { id: MISSION_TARGET, label: 'MISSION', blurb: 'what this run is for' },
  { id: POLICY_TARGET, label: 'POLICY', blurb: 'binds every agent, every message, forever' },
  { id: ROUTE_TARGET, label: 'THOR', blurb: 'say it once, he decides who needs it' },
]);

export function createComposer({
  dom,
  send,
  getAgents,
  getReferences = () => [],
  getTarget,
  getHistory = () => [],
  setTarget,
  onSend,
  dispatch = ({ target, text, attachments }) => send('say', { target, text, attachments }),
  dropTarget = globalThis,
}) {
  if (!dom.input) return { setTarget() {}, focus() {}, beginMission() {} };
  const editor = createMarkdownEditor(dom.input);

  let suggestions = [];
  let highlighted = 0;
  let token = 0;
  let attachments = [];
  let lastMission = '';
  let historyIndex = null;
  let historyDraft = '';
  let historyTarget = null;
  let submitting = false;
  const localHistory = new Map();

  function agentNames() {
    return agentMentionNames(getAgents());
  }

  async function fetchSuggestions(mention) {
    const mine = ++token;
    const list = await lookup(mention, agentNames(), getReferences());
    if (mine !== token) return; // a later keystroke already won
    suggestions = list;
    highlighted = 0;
    renderMenu();
  }

  function renderMenu() {
    if (!dom.menu) return;
    if (suggestions.length === 0) {
      dom.menu.hidden = true;
      dom.menu.replaceChildren();
      return;
    }
    dom.menu.replaceChildren(
      ...suggestions.map((value, index) => {
        const row = document.createElement('div');
        row.className = 'mention-row';
        row.textContent = value;
        row.setAttribute('aria-selected', String(index === highlighted));
        row.onmousedown = (event) => {
          event.preventDefault();
          accept(index);
        };
        return row;
      }),
    );
    dom.menu.hidden = false;
  }

  function closeMenu() {
    suggestions = [];
    renderMenu();
  }

  function accept(index) {
    const mention = editor.mention();
    const value = suggestions[index];
    if (!mention || value === undefined) return;
    const replacement = `${mention.sigil}${value} `;
    if (editor.rich) editor.replaceMention(mention, replacement);
    else {
      const text = editor.value();
      editor.setValue(`${text.slice(0, mention.start)}${replacement}${text.slice(mention.end)}`);
    }
    autosize();
    if (!editor.rich) editor.caretToEnd();
    closeMenu();
    editor.focus();
  }

  async function submit() {
    if (submitting) return;
    const text = editor.value().trim();
    if (!text && attachments.length === 0) return;
    const target = getTarget();
    const sentAttachments = [...attachments];
    submitting = true;
    dom.send.disabled = true;
    dom.input.setAttribute('aria-busy', 'true');
    dom.input.removeAttribute('aria-invalid');
    try {
      const result = await dispatch({ target, text, attachments: sentAttachments });
      if (result?.ok === false) {
        dom.input.setAttribute('aria-invalid', 'true');
        return;
      }
    } catch (error) {
      dom.input.setAttribute('aria-invalid', 'true');
      dom.input.title = error?.message ?? 'Message could not be sent';
      return;
    } finally {
      submitting = false;
      dom.send.disabled = false;
      dom.input.removeAttribute('aria-busy');
    }
    if (text) {
      const sent = localHistory.get(target) ?? [];
      localHistory.set(target, [...sent, text]);
    }
    onSend?.({ target, text, attachments: sentAttachments, from: dom.input.getBoundingClientRect() });
    editor.setValue('');
    historyIndex = null;
    historyDraft = '';
    autosize();
    attachments = [];
    renderAttachments();
    closeMenu();
  }

  function browseHistory(direction) {
    const saved = getHistory()
      .map((message) => String(message ?? '').trim())
      .filter(Boolean);
    const pending = localHistory.get(getTarget()) ?? [];
    let overlap = Math.min(saved.length, pending.length);
    while (overlap > 0 && !pending.slice(0, overlap)
      .every((message, index) => message === saved[saved.length - overlap + index])) {
      overlap -= 1;
    }
    const history = [...saved, ...pending.slice(overlap)];
    if (history.length === 0) return false;

    if (historyIndex === null) {
      historyIndex = history.length;
      historyDraft = editor.value();
    }
    historyIndex = Math.max(0, Math.min(history.length, historyIndex + direction));
    editor.setValue(historyIndex === history.length ? historyDraft : history[historyIndex]);
    autosize();
    editor.caretToEnd();
    return true;
  }

  function atHistoryEdge(direction) {
    return editor.atHistoryEdge(direction);
  }

  // Files travel to disk first: an agent is given a path, never bytes.
  async function attach(files) {
    for (const file of files) {
      const response = await fetch('/upload', {
        method: 'POST',
        headers: { 'x-filename': encodeURIComponent(file.name) },
        body: file,
      });
      const body = await response.json();
      if (body.ok) attachments = [...attachments, body.file];
      else showError(body.error);
    }
    renderAttachments();
  }

  function renderAttachments() {
    if (!dom.attachments) return;
    dom.attachments.replaceChildren(
      ...attachments.map((file) => {
        const chip = document.createElement('span');
        chip.className = 'chip';
        chip.title = `${file.type} · ${Math.round(file.bytes / 1024)}KB`;
        // Baseline so a chip is always readable and removable, with or without
        // the stylesheet: the label truncates, the × never does.
        chip.style.cssText = [
          'display:inline-flex', 'align-items:center', 'gap:6px', 'max-width:280px',
          'padding:2px 6px', 'border:1px solid var(--line,#262626)', 'margin:0 4px 4px 0',
        ].join(';');

        // An image says what it is far better than its filename does.
        if (String(file.type ?? '').startsWith('image/')) {
          const thumb = document.createElement('img');
          thumb.src = `/attachment?path=${encodeURIComponent(file.path)}`;
          thumb.alt = file.name;
          thumb.style.cssText =
            'width:34px;height:34px;object-fit:cover;display:block;flex:none;'
            + 'border:1px solid var(--line,#262626)';
          chip.style.padding = '2px 6px 2px 2px';
          chip.append(thumb);
        } else {
          const label = document.createElement('span');
          label.textContent = file.name;
          label.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
          chip.append(label);
        }

        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'chip-x';
        remove.textContent = '×';
        remove.setAttribute('aria-label', `remove ${file.name}`);
        remove.style.cssText = [
          'flex:none', 'background:transparent', 'border:0', 'cursor:pointer',
          'color:var(--muted,#8a8a8a)', 'font:inherit', 'font-size:14px', 'line-height:1',
          'padding:0 2px',
        ].join(';');
        remove.onclick = () => {
          attachments = attachments.filter((candidate) => candidate !== file);
          renderAttachments();
        };
        chip.append(remove);
        return chip;
      }),
    );
    dom.attachments.hidden = attachments.length === 0;
  }

  function showError(message) {
    if (!dom.attachments) return;
    dom.attachments.hidden = false;
    const line = document.createElement('span');
    line.className = 'chip error';
    line.textContent = message;
    dom.attachments.append(line);
    setTimeout(() => line.remove(), 5000);
  }

  // The box grows with the text, up to a point, then scrolls. Nothing typed is
  // ever hidden behind a one-line window.
  const MAX_HEIGHT = () => Math.round(window.innerHeight * 0.35);

  function autosize() {
    if (dom.input.tagName !== 'TEXTAREA') return;
    dom.input.style.height = 'auto';
    const wanted = dom.input.scrollHeight;
    const cap = MAX_HEIGHT();
    dom.input.style.height = `${Math.min(wanted, cap)}px`;
    dom.input.style.overflowY = wanted > cap ? 'auto' : 'hidden';
  }

  dom.input.addEventListener('input', () => {
    historyIndex = null;
    historyDraft = '';
    autosize();
    editor.formatInput();
    const mention = editor.mention();
    if (!mention) return closeMenu();
    fetchSuggestions(mention);
  });
  addEventListener('resize', autosize);

  dom.input.addEventListener('keydown', (event) => {
    if (suggestions.length > 0) {
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault();
        const step = event.key === 'ArrowDown' ? 1 : -1;
        highlighted = (highlighted + step + suggestions.length) % suggestions.length;
        return renderMenu();
      }
      if (event.key === 'Tab' || (event.key === 'Enter' && !event.shiftKey)) {
        event.preventDefault();
        return accept(highlighted);
      }
      if (event.key === 'Escape') {
        event.preventDefault();
        return closeMenu();
      }
    }
    if ((event.key === 'ArrowUp' || event.key === 'ArrowDown')
      && !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey) {
      const direction = event.key === 'ArrowUp' ? -1 : 1;
      if (atHistoryEdge(direction) && browseHistory(direction)) {
        event.preventDefault();
        return;
      }
    }
    // Nothing to dismiss, so Escape steps back out to the mission.
    if (event.key === 'Escape' && getTarget() !== MISSION_TARGET) {
      event.preventDefault();
      return setTarget?.(MISSION_TARGET);
    }
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      submit();
    }
  });

  // The target chip is the way back: it says who you are talking to, and
  // pressing it returns you to the mission.
  if (dom.targetChip) {
    dom.targetChip.setAttribute('role', 'button');
    dom.targetChip.setAttribute('tabindex', '0');
    dom.targetChip.title = 'Click to address the mission instead';
    dom.targetChip.style.cursor = 'pointer';
    // Clicking the chip cycles the three ways of speaking once: MISSION, then
    // POLICY, then THOR. Standing at a desk, the first click steps back out.
    const toMission = () => {
      const here = getTarget?.();
      const index = SPEAK_TARGETS.findIndex((t) => t.id === here);
      const next = index === -1
        ? MISSION_TARGET
        : SPEAK_TARGETS[(index + 1) % SPEAK_TARGETS.length].id;
      setTarget?.(next);
      editor.focus();
    };
    dom.targetChip.addEventListener('click', toMission);
    dom.targetChip.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        toMission();
      }
    });
  }

  dom.send?.addEventListener('click', submit);
  dom.file?.addEventListener('change', () => {
    attach([...dom.file.files]);
    dom.file.value = '';
  });

  // Dropping anywhere on the window attaches, so you never have to aim.
  const stop = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };
  for (const type of ['dragenter', 'dragover']) {
    dropTarget.addEventListener(type, (event) => {
      stop(event);
      document.body.classList.add('dropping');
    });
  }
  for (const type of ['dragleave', 'drop']) {
    dropTarget.addEventListener(type, (event) => {
      stop(event);
      if (type === 'dragleave' && event.relatedTarget) return;
      document.body.classList.remove('dropping');
    });
  }
  dropTarget.addEventListener('drop', (event) => {
    const files = [...(event.dataTransfer?.files ?? [])];
    if (files.length > 0) attach(files);
  });

  dom.input.addEventListener('paste', (event) => {
    const files = [...(event.clipboardData?.files ?? [])];
    if (files.length > 0) {
      event.preventDefault();
      attach(files);
      return;
    }
    editor.paste(event);
  });
  dom.input.addEventListener('blur', () => setTimeout(closeMenu, 120));

  return {
    // A new run starts with one empty mission draft. The server owns the run;
    // this only clears the old run's local editor state after that succeeds.
    beginMission() {
      lastMission = '';
      historyTarget = MISSION_TARGET;
      historyIndex = null;
      historyDraft = '';
      editor.setValue('');
      attachments = [];
      renderAttachments();
      closeMenu();
      autosize();
      editor.focus();
    },
    // Addressing the mission shows the mission that is already set, so it can
    // be edited rather than retyped from memory. Never while you are typing:
    // a redraw must not overwrite what is in your hands.
    setTarget(target, agents, mission = '') {
      if (historyTarget !== target) {
        historyTarget = target;
        historyIndex = null;
        historyDraft = '';
      }
      if (dom.targetChip) {
        const agent = agents.find((candidate) => candidate.id === target);
        const preset = SPEAK_TARGETS.find((t) => t.id === target);
        dom.targetChip.textContent = agent
          ? `→ ${agent.label ?? agent.name}`
          : (preset?.label ?? 'MISSION');
        dom.targetChip.title = preset?.blurb ?? '';
      }
      if (!dom.input) return;
      const targetAgent = agents.find((candidate) => candidate.id === target);
      const toMission = target === MISSION_TARGET;
      editor.setPlaceholder(toMission
        ? 'set the mission · @file /skill @agent #checkpoint'
        : target === POLICY_TARGET
          ? 'a rule every agent obeys, on every message, from now on'
          : target === ROUTE_TARGET
            ? 'say it once - Thor decides who needs to hear it'
            : `talk to ${targetAgent?.label ?? target} · @file /skill @agent #checkpoint`);

      const typing = document.activeElement === dom.input;
      if (typing) return;
      if (toMission) {
        // Only when the box holds nothing of yours, or the last mission we put
        // there ourselves - never clobber a draft.
        if (!editor.value() || editor.value() === lastMission) {
          editor.setValue(mission ?? '');
          lastMission = mission ?? '';
        }
      } else if (editor.value() && editor.value() === lastMission) {
        editor.setValue(''); // that was the mission, not a steer for this agent
      }
    },
    focus() {
      editor.focus();
    },
    parse(text) {
      const references = getReferences();
      return parseMentions(text, {
        agents: getAgents(),
        checkpoints: references.filter((item) => item.kind === 'checkpoint'),
        decisions: references.filter((item) => item.kind === 'decision'),
      });
    },
  };
}

async function lookup(mention, agentNames, references) {
  if (mention.sigil === '/') {
    const { skills } = await getJson('/skills');
    return filter(skills, mention.query);
  }
  if (mention.sigil === '#') {
    return filter(references.map((item) => item.id), mention.query);
  }
  const named = filter(agentNames, mention.query);
  const { files } = await getJson(`/files?q=${encodeURIComponent(mention.query)}`);
  return [...named, ...files].slice(0, 20);
}

async function getJson(url) {
  try {
    const response = await fetch(url);
    return await response.json();
  } catch {
    return {};
  }
}

function filter(list = [], query) {
  if (!query) return list.slice(0, 8);
  const needle = query.toLowerCase();
  return list.filter((value) => value.toLowerCase().includes(needle)).slice(0, 8);
}

// Zero-dependency MCP stdio adapter. Each engine session launches one copy.
// It contains no fleet policy: it lists the shared core catalogue and forwards
// calls to the one running MINIMAC server that owns the state.

import { createInterface } from 'node:readline';
import { toolsForRole } from '../core/agent-tools.mjs';

const role = process.env.MINIMAC_AGENT_ROLE ?? '';
const url = process.env.MINIMAC_SERVER_URL ?? '';
const token = [REDACTED] ?? '';
const tools = toolsForRole(role);

const input = createInterface({ input: process.stdin, crlfDelay: Infinity });
input.on('line', (line) => void receive(line));

async function receive(line) {
  let request;
  try {
    request = JSON.parse(line);
  } catch {
    return;
  }
  if (request.id === undefined) return;

  try {
    const result = await handle(request.method, request.params ?? {});
    write({ jsonrpc: '2.0', id: request.id, result });
  } catch (error) {
    write({
      jsonrpc: '2.0',
      id: request.id,
      error: { code: -32603, message: error?.message ?? String(error) },
    });
  }
}

async function handle(method, params) {
  if (method === 'initialize') {
    return {
      protocolVersion: params.protocolVersion ?? '2025-06-18',
      capabilities: { tools: { listChanged: false } },
      serverInfo: { name: 'minimac', version: '0.1.0' },
    };
  }
  if (method === 'ping') return {};
  if (method === 'tools/list') return { tools };
  if (method !== 'tools/call') throw new Error(`method not found: ${method}`);

  const response = await fetch(`${url}/agent-tool`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({ name: params.name, arguments: params.arguments ?? {} }),
  });
  const body = await response.json();
  return {
    content: [{ type: 'text', text: body.ok ? JSON.stringify(body.result ?? {}) : body.error }],
    isError: !body.ok,
  };
}

function write(message) {
  process.stdout.write(`${JSON.stringify(message)}\n`);
}

// The only place that fetches geometry. Everything above it asks for a model
// by name and gets a fresh instance back, already centred, shadowed and ready
// to place. Kenney CC0 kits, loaded once and cloned per instance.

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.1/+esm';
import { GLTFLoader } from 'https://cdn.jsdelivr.net/npm/three@0.160.1/examples/jsm/loaders/GLTFLoader.js/+esm';
import { clone as cloneSkinned } from 'https://cdn.jsdelivr.net/npm/three@0.160.1/examples/jsm/utils/SkeletonUtils.js/+esm';
import { identityModels } from './identity.mjs';

const FURNITURE = '/assets/furniture';
const PEOPLE = '/assets/people';

export const PEOPLE_MODELS = Object.freeze([
  'character-male-a',
  'character-female-a',
  'character-male-b',
  'character-female-b',
  'character-male-c',
  'character-female-c',
  'character-male-d',
  'character-female-d',
]);

export const FURNITURE_MODELS = Object.freeze([
  'desk',
  'chairDesk',
  'computerScreen',
  'computerKeyboard',
  'computerMouse',
  'lampRoundTable',
  'wall',
  'wallWindow',
  'rugRectangle',
  'rugRound',
  'loungeSofa',
  'loungeChair',
  'tableCoffee',
  'books',
  'bookcaseOpen',
  'bookcaseClosedWide',
  'kitchenCabinet',
  'kitchenCoffeeMachine',
  'stoolBar',
  'pottedPlant',
  'plantSmall1',
  'plantSmall2',
  'plantSmall3',
  'lampSquareFloor',
  'trashcan',
  'cardboardBoxClosed',
]);

const isPerson = (name) => name.startsWith('character-');

// A loaded model: the prototype scene plus its animation clips. The identity
// table is a second source of model names, so it is unioned in here rather
// than duplicated by hand.
export async function loadModels() {
  const loader = new GLTFLoader();
  const load = (url) => loader.loadAsync(url);
  const wanted = identityModels();
  const furniture = [...new Set([...FURNITURE_MODELS, ...wanted.filter((n) => !isPerson(n))])];
  const people = [...new Set([...PEOPLE_MODELS, ...wanted.filter(isPerson)])];
  const entries = await Promise.all([
    ...furniture.map(async (name) => [name, await load(`${FURNITURE}/${name}.glb`)]),
    ...people.map(async (name) => [name, await load(`${PEOPLE}/${name}.glb`)]),
  ]);
  const models = new Map();
  for (const [name, gltf] of entries) {
    prepare(gltf.scene);
    models.set(name, { scene: gltf.scene, clips: gltf.animations ?? [] });
  }
  return models;
}

// Kenney's kit ships a bright salmon-and-pine palette. Off Grid is near-black
// with a single emerald accent, so the kit is regraded once, on load, by
// material name - one table rather than a tint scattered through the scene.
const MATERIAL_COLOURS = Object.freeze({
  carpet: '#333d3a',
  carpetDarker: '#242c2a',
  carpetWhite: '#c9d1ce',
  wood: '#6d5439',
  woodDark: '#4a3826',
  metal: '#9ba7a8',
  metalDark: '#2b3232',
  metalMedium: '#485252',
  lamp: '#ffe9a0',
  glass: '#8fa8a0',
  plant: '#4d7f66',
  _defaultMat: '#98a09e',
});

// Everything the renderer needs to be true of every mesh, applied once.
function prepare(root) {
  root.traverse((node) => {
    if (!node.isMesh) return;
    node.castShadow = true;
    node.receiveShadow = true;
    const materials = Array.isArray(node.material) ? node.material : [node.material];
    for (const material of materials) {
      if (!material) continue;
      material.side = THREE.FrontSide;
      const graded = MATERIAL_COLOURS[material.name];
      if (graded) material.color.set(graded);
      if ('roughness' in material) material.roughness = Math.min(material.roughness ?? 1, 0.88);
      if ('metalness' in material) material.metalness = 0;
    }
  });
}

// A placeable instance, wrapped in a group whose origin is on the floor at the
// model's horizontal centre. Callers position by that centre and never have to
// know the kit's authoring origin. `targetHeight` normalises a model of unknown
// scale - which is every model a user drops in themselves.
export function build(model, { targetHeight } = {}) {
  const object = cloneSkinned(model.scene);
  const box = new THREE.Box3().setFromObject(object);
  const size = box.getSize(new THREE.Vector3());
  const centre = box.getCenter(new THREE.Vector3());
  const scale = targetHeight && size.y > 0 ? targetHeight / size.y : 1;
  object.scale.setScalar(scale);
  object.position.set(-centre.x * scale, -box.min.y * scale, -centre.z * scale);

  const group = new THREE.Group();
  group.add(object);
  group.userData.size = size;
  group.userData.clips = model.clips;
  return group;
}

export function instance(models, name, options) {
  const model = models.get(name);
  if (!model) throw new Error(`model not loaded: ${name}`);
  return build(model, options);
}

// Roster-supplied characters. The directory is deliberately optional and
// usually empty, so a miss is a silent fall back to the built-in look - never
// an error the user has to read.
const custom = new Map();

export function customModel(path) {
  if (!path) return null;
  const url = path.startsWith('/') ? path : `/${path}`;
  let entry = custom.get(url);
  if (entry) return entry;
  entry = { status: 'pending', model: null };
  custom.set(url, entry);
  new GLTFLoader()
    .loadAsync(encodeURI(url))
    .then((gltf) => {
      prepare(gltf.scene);
      entry.model = { scene: gltf.scene, clips: gltf.animations ?? [] };
      entry.status = 'ready';
    })
    .catch(() => {
      entry.status = 'missing';
    });
  return entry;
}

// Materials are shared across clones, so anything per-instance (an emissive
// screen, a tint) has to own its own copy first.
export function isolateMaterials(root) {
  root.traverse((node) => {
    if (!node.isMesh) return;
    node.material = Array.isArray(node.material)
      ? node.material.map((material) => material.clone())
      : node.material.clone();
  });
}

export function findMaterial(root, name) {
  let found = null;
  root.traverse((node) => {
    if (found || !node.isMesh) return;
    const materials = Array.isArray(node.material) ? node.material : [node.material];
    const hit = materials.find((material) => material?.name === name);
    if (hit) found = hit;
  });
  return found;
}

